        String keyword,
        List<Long> categoryIds,
        List<Xbj22Type> genders,
        List<Long> brandIds,
        List<Long> collectionIds,
        List<String> colors,
        List<String> sizes,
        Integer minPrice,
        Integer maxPrice,
        Xpk87 sortOption,
        Pageable pageable) {

    QXkr46 product = QXkr46.xkr46;
    QXfp92 productColor = QXfp92.xfp92;
    QXdh20 productSize = QXdh20.xdh20;
    QXrf21 interest = QXrf21.xrf21;
