            .distinct();


    if (sortOption != null) {
        if ("price".equalsIgnoreCase(sortOption.getField())) {
            query.orderBy("asc".equalsIgnoreCase(sortOption.getOrder())
                    ? productSize.purchasePrice.min().asc()
                    : productSize.purchasePrice.min().desc());
